//! 🛂️ Exact forwarded allocation admission retains the original receiving owner.
use crate::native_encoding::{NativeEncodeControl,NativeEncodeAllocation,NativeForwardedEncodeControl};
use crate::{ValueError,ValueRefusalKind};
use std::sync::atomic::{AtomicUsize,Ordering};
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
#[test]
fn forwarded_allocation_precedes_every_small_owned_span_and_retains_the_same_authority(){
 let neutral=fixture();let law=&neutral["ownership"];let ceiling=law["ceiling"].as_u64().unwrap()as usize;
 let prior:Vec<u8>=serde_json::from_value(law["prior"].clone()).unwrap();let text=law["text"].as_str().unwrap();let pointer=text.as_ptr();let calls=AtomicUsize::new(0);
 let mut host_progress=|_|true;let mut host_receipt=Some(NativeEncodeControl::new(ceiling,&mut host_progress).pause().unwrap());
 let mut allocate=|request:NativeEncodeAllocation|{let mut host=NativeEncodeControl::resume(host_receipt.take().unwrap(),&mut host_progress).unwrap();assert_eq!(request.owned_bytes,host.owned_bytes());assert_eq!(request.next_owned_bytes,request.owned_bytes+request.bytes);assert_eq!(request.maximum_bytes,ceiling);calls.fetch_add(1,Ordering::Relaxed);let result=host.charge(request.bytes);host_receipt=Some(host.pause().unwrap());result};
 let mut progress=|_|true;let mut guest=NativeEncodeControl::new_forwarded(ceiling,&mut progress,&mut allocate);
 let copied=guest.copy_bytes(&prior).unwrap();let output=guest.copy_text(text).unwrap();assert_eq!(calls.load(Ordering::Relaxed),2);assert_eq!(copied,prior);assert_eq!(serde_json::to_string(&output).unwrap(),serde_json::to_string(text).unwrap());
 let receipt=guest.pause().unwrap();let mut next_progress=|_|true;let mut resumed=NativeForwardedEncodeControl::resume(receipt,&mut next_progress).unwrap();
 assert_eq!(resumed.copy_text(law["tail"].as_str().unwrap()).unwrap(),"x");assert_eq!(resumed.owned_bytes(),law["expected"].as_u64().unwrap()as usize);assert_eq!(calls.load(Ordering::Relaxed),3);assert_eq!(text.as_ptr(),pointer);
 drop(resumed);drop(allocate);let host=NativeEncodeControl::resume(host_receipt.take().unwrap(),&mut host_progress).unwrap();assert_eq!(host.owned_bytes(),law["expected"].as_u64().unwrap()as usize);
 #[cfg(not(target_arch="wasm32"))]{fn assert_send<T:Send>(){}assert_send::<crate::native_encoding::NativeForwardedEncodeContinuation<'static>>();}
 println!("[DEBUG] Forwarded native allocation: calls=3 ordinarySmallSpans=true originalOwnerRetainedAcrossPause=true exactHostAndGuestOwnership=true independentSerde=true sourcePointerPreserved=true");
}
#[test]
fn forwarded_allocation_refuses_before_reserving_storage_and_preserves_the_original_ledger(){
 let neutral=fixture();let bytes=neutral["refusedBytes"].as_u64().unwrap()as usize;let source="x".repeat(bytes);let pointer=source.as_ptr();
 for kind in [ValueRefusalKind::OwnershipLimit,ValueRefusalKind::Canceled]{let calls=AtomicUsize::new(0);let mut allocate=|request:NativeEncodeAllocation|{calls.fetch_add(1,Ordering::Relaxed);assert_eq!(request.owned_bytes,0);assert_eq!(request.bytes,bytes);Err(ValueError::literal(kind,"original receiving authority refused allocation"))};let mut progress=|_|true;let mut control=NativeEncodeControl::new_forwarded(bytes,&mut progress,&mut allocate);let error=control.copy_text(&source).unwrap_err();assert_eq!(error.kind,kind);assert_eq!(control.owned_bytes(),0);assert_eq!(calls.load(Ordering::Relaxed),1);assert_eq!(source.as_ptr(),pointer);}
 let calls=AtomicUsize::new(0);let mut allocate=|_:NativeEncodeAllocation|{calls.fetch_add(1,Ordering::Relaxed);Ok(())};let mut progress=|_|true;let mut zero=NativeEncodeControl::new_forwarded(0,&mut progress,&mut allocate);assert_eq!(zero.copy_text(&source).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(calls.load(Ordering::Relaxed),0);assert_eq!(zero.owned_bytes(),0);
 println!("[DEBUG] Forwarded native allocation refusal: cases=3 zeroOwnershipPreserved=true originalPortBeforeAllocation=true finiteLocalCeilingBeforeForward=true");
}

#[test]
fn retained_forwarded_hops_keep_the_original_receipt_on_work_and_allocation_refusal(){
 use std::sync::atomic::AtomicBool;
 let neutral=fixture();let law=&neutral["hops"];let ceiling=law["ceiling"].as_u64().unwrap()as usize;let bytes:Vec<u8>=serde_json::from_value(law["nextBytes"].clone()).unwrap();let allowed=AtomicBool::new(true);let calls=AtomicUsize::new(0);
 let mut host_progress=|_|true;let mut host_receipt=Some(NativeEncodeControl::new(ceiling,&mut host_progress).pause().unwrap());
 let mut allocate=|request:NativeEncodeAllocation|{calls.fetch_add(1,Ordering::Relaxed);if !allowed.load(Ordering::Relaxed){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original retained receiving lifetime closed"))}let mut host=NativeEncodeControl::resume(host_receipt.take().unwrap(),&mut host_progress).unwrap();assert_eq!(host.owned_bytes(),request.owned_bytes);let result=host.charge(request.bytes);host_receipt=Some(host.pause().unwrap());result};
 let mut progress=|_|true;let mut receipt=NativeEncodeControl::new_forwarded(ceiling,&mut progress,&mut allocate).pause().unwrap();
 let mut first=|_|true;let error=receipt.encode(&mut first,|control|{control.charge(law["firstCharge"].as_u64().unwrap()as usize)?;control.begin_stage(law["declaredWork"].as_u64().unwrap()as usize)?;control.advance(law["refusedWork"].as_u64().unwrap()as usize)}).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::WorkLimit);assert_eq!(receipt.owned_bytes(),3);
 allowed.store(false,Ordering::Relaxed);let mut next=|_|true;assert_eq!(receipt.encode(&mut next,|control|control.copy_bytes(&bytes)).unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(receipt.owned_bytes(),3);assert_eq!(receipt.maximum_bytes(),ceiling);
 allowed.store(true,Ordering::Relaxed);let mut final_progress=|_|true;assert_eq!(receipt.encode(&mut final_progress,|control|control.copy_bytes(&bytes)).unwrap(),bytes);assert_eq!(receipt.owned_bytes(),law["expected"].as_u64().unwrap()as usize);assert_eq!(calls.load(Ordering::Relaxed),3);drop(receipt);drop(allocate);let host=NativeEncodeControl::resume(host_receipt.take().unwrap(),&mut host_progress).unwrap();assert_eq!(host.owned_bytes(),5);
 println!("[DEBUG] Retained forwarded native receiving: hops=3 workRefusalRetainsOwned=3 originalCancelBeforeAllocation=true recoveredOwned=5 originalPortCalls=3 sameHostReceipt=true");
}

#[test]
fn direct_original_port_receipt_composes_short_observers_without_resetting_admission(){
 let neutral=fixture();let law=&neutral["observer"];let ceiling=law["ceiling"].as_u64().unwrap()as usize;let text=law["text"].as_str().unwrap();let calls=AtomicUsize::new(0);let original_progress=AtomicUsize::new(0);let phase_progress=AtomicUsize::new(0);
 let mut allocate=|request:NativeEncodeAllocation|{calls.fetch_add(1,Ordering::Relaxed);assert_eq!(request.bytes,text.len());assert_eq!(request.owned_bytes,0);assert_eq!(request.next_owned_bytes,text.len());assert_eq!(request.maximum_bytes,ceiling);Ok(())};
 let mut receipt=crate::native_encoding::NativeForwardedEncodeContinuation::new(ceiling,&mut allocate);assert_eq!(receipt.owned_bytes(),0);assert_eq!(receipt.maximum_bytes(),ceiling);assert_eq!(calls.load(Ordering::Relaxed),0);
 let mut original=|_|{original_progress.fetch_add(1,Ordering::Relaxed);true};let mut canceled=|_|{phase_progress.fetch_add(1,Ordering::Relaxed);false};
 let error=receipt.encode(&mut original,|control|control.scoped_observer(&mut canceled,|scoped|scoped.copy_text(text))).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(receipt.owned_bytes(),0);assert_eq!(calls.load(Ordering::Relaxed),0);assert_eq!(original_progress.load(Ordering::Relaxed),1);assert_eq!(phase_progress.load(Ordering::Relaxed),1);
 let mut phase=|_|{phase_progress.fetch_add(1,Ordering::Relaxed);true};let output=receipt.encode(&mut original,|control|control.scoped_observer(&mut phase,|scoped|scoped.copy_text(text))).unwrap();assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::to_value(text).unwrap());assert_eq!(receipt.owned_bytes(),text.len());assert_eq!(calls.load(Ordering::Relaxed),1);assert_eq!(original_progress.load(Ordering::Relaxed),3);assert_eq!(phase_progress.load(Ordering::Relaxed),3);
 let mut canceled_original=|_|{original_progress.fetch_add(1,Ordering::Relaxed);false};assert_eq!(receipt.encode(&mut canceled_original,|control|control.scoped_observer(&mut phase,|scoped|scoped.checkpoint())).unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(receipt.owned_bytes(),text.len());assert_eq!(original_progress.load(Ordering::Relaxed),4);assert_eq!(phase_progress.load(Ordering::Relaxed),3);
 println!("[DEBUG] Native original port receipt: directBindingWithoutDummyProgress=true phaseCancellationBeforeAllocation=true exactOriginalObserver=true forwardedLedgerRetained=true independentSerde=true");
}

#[test]
fn encoder_original_retirement_slot_survives_pause_and_refused_hops(){
 let law=fixture();let bytes=law["wrapperBytes"].as_u64().unwrap()as usize;let calls=AtomicUsize::new(0);let mut allocate=|_:NativeEncodeAllocation|{calls.fetch_add(1,Ordering::Relaxed);Ok(())};let mut recipient=crate::native_encoding::NativeEncodeRetirementRecipient::new();let mut progress=|_|true;let mut control=NativeEncodeControl::new_forwarded(bytes*3,&mut progress,&mut allocate);control.install_retirement_recipient(&mut recipient).unwrap();let mut receipt=control.pause().unwrap();let mut next=|_|true;
 let error=receipt.encode(&mut next,|control|control.with_retirement_owner(bytes,|_|(Err::<(),_>(ValueError::literal(ValueRefusalKind::InvalidValue,"partial owner refused")),None))).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!(receipt.owned_bytes(),bytes);
 receipt.encode(&mut next,|control|control.scoped_observer(&mut | _ |true,|child|child.with_retirement_owner(bytes,|_|(Ok(()),None)))).unwrap();assert_eq!(receipt.owned_bytes(),bytes*2);assert_eq!(calls.load(Ordering::Relaxed),2);drop(receipt);assert!(!recipient.has_owner());
 println!("[DEBUG] Encoder original retirement recipient: survivesPause=true refusedHopReservedSlotRestored=true scopedObserverPreservesRecipient=true cumulativeOwned=16");
}

#[test]
fn encoder_refused_partial_owner_returns_to_the_same_original_recipient(){
 use semio_framework_value::{ErasedSnapshotRetirement,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
 use std::sync::Arc;
 struct Owner{bytes:Option<Vec<u8>>,drops:Arc<AtomicUsize>}
 impl Drop for Owner{fn drop(&mut self){assert!(self.bytes.is_none());self.drops.fetch_add(1,Ordering::Relaxed);}}
 impl ErasedSnapshotRetirement for Owner{
  fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if grant.maximum_items==0{return Ok(RetainedCloneStep::Progress(Default::default()))}let released=self.next_release_byte_demand()?;if released>grant.maximum_release_bytes{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original retained release grant refused"))}self.bytes.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:released,..Default::default()}))}
  fn terminal_is_empty(&self)->bool{self.bytes.is_none()}
  fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
  fn next_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
  fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.bytes.as_ref().map_or(0,Vec::capacity))}
  fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}
 }
 let law=fixture();let payload:Vec<u8>=serde_json::from_value(law["retainedPayload"].clone()).unwrap();let drops=Arc::new(AtomicUsize::new(0));let bytes=std::mem::size_of::<Owner>()+payload.len();let calls=AtomicUsize::new(0);let mut allocate=|_:NativeEncodeAllocation|{calls.fetch_add(1,Ordering::Relaxed);Ok(())};let mut recipient=crate::native_encoding::NativeEncodeRetirementRecipient::new();let mut receipt=crate::native_encoding::NativeForwardedEncodeContinuation::new(bytes,&mut allocate);receipt.install_retirement_recipient(&mut recipient).unwrap();let mut progress=|_|true;
 let error=receipt.encode(&mut progress,|control|control.with_retirement_owner(std::mem::size_of::<Owner>(),|control|match control.copy_bytes(&payload){Err(error)=>(Err::<(),_>(error),None),Ok(owned)=>(Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original typed construction refused")),Some(Box::new(Owner{bytes:Some(owned),drops:drops.clone()})as Box<dyn ErasedSnapshotRetirement>))})).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!(receipt.owned_bytes(),bytes);assert_eq!(calls.load(Ordering::Relaxed),2);assert_eq!(drops.load(Ordering::Relaxed),0);drop(receipt);assert!(recipient.has_owner());
 let denied=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};assert_eq!(recipient.close_step(denied).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(drops.load(Ordering::Relaxed),0);let granted=RetainedCloneGrant{maximum_items:1,maximum_release_bytes:bytes,maximum_depth:2,..Default::default()};while !recipient.terminal_is_empty(){recipient.close_step(granted).unwrap();}assert_eq!(drops.load(Ordering::Relaxed),1);
 println!("[DEBUG] Encoder original partial owner: originalRecipientRetained=true refusalReturnsPhysicalPayload=true preadmittedWrapper=true zeroReleaseGrantPreservesOwner=true boundedDrainDropsExactlyOnce=true");
}

#[test]
fn native_consuming_receipt_retains_original_retirement_recipient_across_short_progress_hops(){
 use semio_framework_value::{retirement::controlled::ControlledRetirement,ErasedSnapshotRetirement};
 let neutral=fixture();let law=&neutral["retainedNative"];let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(law["grant"].clone()).unwrap();let text=law["copy"].as_str().unwrap();let pointer=text.as_ptr();let mut recipient=crate::native_encoding::NativeEncodeRetirementRecipient::new();let events=AtomicUsize::new(0);let mut progress=|_|{events.fetch_add(1,Ordering::Relaxed);true};let mut original=NativeEncodeControl::new(law["maximumBytes"].as_u64().unwrap()as usize,&mut progress);original.charge(law["initialBytes"].as_u64().unwrap()as usize).unwrap();let mut receipt=original.pause().unwrap().with_retirement_recipient(&mut recipient).unwrap();let wrapper=std::mem::size_of::<ControlledRetirement<String>>();
 let error=receipt.encode(&mut progress,|control|control.with_retirement_owner(wrapper,|control|match control.copy_text(text){Err(error)=>(Err::<(),_>(error),None),Ok(owned)=>{assert_eq!(serde_json::to_value(&owned).unwrap(),serde_json::to_value(text).unwrap());(Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original native checkpoint refuses after physical ownership")),Some(Box::new(ControlledRetirement::new(owned).ok().unwrap())as Box<dyn ErasedSnapshotRetirement>))}})).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);let retained=receipt.owned_bytes();assert_eq!(retained,law["initialBytes"].as_u64().unwrap()as usize+wrapper+text.len());let mut canceled=|_|false;assert_eq!(receipt.encode(&mut canceled,|control|control.close_retirement_recipient(grant)).unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(receipt.owned_bytes(),retained);
 receipt.encode(&mut progress,|control|{while control.has_retirement_owner(){control.close_retirement_recipient(grant)?;}Ok(())}).unwrap();assert!(receipt.owned_bytes()>retained);assert_eq!(receipt.maximum_bytes(),law["maximumBytes"].as_u64().unwrap()as usize);drop(receipt);assert!(!recipient.has_owner());assert!(events.load(Ordering::Relaxed)>1);assert_eq!(text.as_ptr(),pointer);println!("[DEBUG] Native original retirement continuation consumingReceipt=true sameRecipient=true noFabricatedForwardedPort=true refusedHopKeepsOwner=true originalCumulativeLedger=true independentSerde=true");
}

#[test]
fn native_recipient_binding_refusal_returns_its_original_consuming_receipt(){
 use semio_framework_value::{retirement::controlled::ControlledRetirement,ErasedSnapshotRetirement};
 let neutral=fixture();let law=&neutral["retainedNative"];let grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(law["grant"].clone()).unwrap();let text=law["copy"].as_str().unwrap();let mut recipient=crate::native_encoding::NativeEncodeRetirementRecipient::new();let live=std::sync::atomic::AtomicBool::new(true);let mut progress=|_|live.load(Ordering::Relaxed);let mut native=NativeEncodeControl::new(law["maximumBytes"].as_u64().unwrap()as usize,&mut progress);native.charge(law["initialBytes"].as_u64().unwrap()as usize).unwrap();native.install_retirement_recipient(&mut recipient).unwrap();let error=native.with_retirement_owner(std::mem::size_of::<ControlledRetirement<String>>(),|native|{let owned=native.copy_text(text).unwrap();assert_eq!(serde_json::to_value(&owned).unwrap(),serde_json::to_value(text).unwrap());(Err::<(),_>(ValueError::literal(ValueRefusalKind::InvalidValue,"actual checkpoint returns original partial owner")),Some(Box::new(ControlledRetirement::new(owned).ok().unwrap())as Box<dyn ErasedSnapshotRetirement>))}).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);let expected=native.owned_bytes();let continuation=native.pause_with_retirement().unwrap();assert_eq!(continuation.owned_bytes(),expected);let(original,recipient)=continuation.into_parts();assert_eq!(original.owned_bytes(),expected);assert_eq!(original.maximum_bytes(),law["maximumBytes"].as_u64().unwrap()as usize);assert!(recipient.has_owner());let(error,original)=match original.with_retirement_recipient(recipient){Ok(_)=>panic!("occupied original recipient must refuse binding"),Err(refused)=>refused};assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);let mut resumed_progress=|_|live.load(Ordering::Relaxed);let mut native=NativeEncodeControl::resume(original,&mut resumed_progress).unwrap();assert_eq!(native.owned_bytes(),expected);while recipient.has_owner(){native.checkpoint().unwrap();let capacity=recipient.next_capacity_byte_demand(grant.maximum_copy_bytes).unwrap();assert!(capacity<=grant.maximum_capacity_bytes);assert!(recipient.next_copy_byte_demand().unwrap()<=grant.maximum_copy_bytes);assert!(recipient.next_release_byte_demand().unwrap()<=grant.maximum_release_bytes);assert!(recipient.next_depth_demand().unwrap()<=grant.maximum_depth);native.charge(capacity).unwrap();recipient.close_step(grant).unwrap();}assert!(native.owned_bytes()>expected);drop(native);assert!(!recipient.has_owner());println!("[DEBUG] Native original binding refusal originalReceiptReturned=true sameRecipient=true admittedBytesConserved=true independentSerde=true noDummyAuthority=true");
}
